#!/usr/bin/env python3
"""Regenerate the GUI font from Inter (https://github.com/rsms/inter, SIL OFL
1.1, see LICENSE.txt; the app ships a subset of Inter 4.1's Regular).

    python3 -m pip install fonttools
    python3 subset.py <Inter-4.1.zip>/extras/ttf/Inter-Regular.ttf

Writes, next to this script:
  Inter-Regular.subset.ttf  the outlines of the codepoints in BLOCKS, without
                            hinting, kerning or OpenType layout (raylib uses
                            none of them); the name table keeps the copyright
                            and license. CMakeLists.txt compiles it into the app.
  inter_subset.h            the codepoints the subset maps and the widths of
                            its blank glyphs, for src/ui.c.

Combining marks are left out: raylib advances by their bitmap width, so
they would push the text apart instead of sitting on the previous letter.
"""
import os
import sys

from fontTools import subset
from fontTools.ttLib import TTFont

BLOCKS = [
    (0x0020, 0x007E),  # Basic Latin
    (0x00A0, 0x00FF),  # Latin-1 Supplement
    (0x0100, 0x017F),  # Latin Extended-A
    (0x0180, 0x024F),  # Latin Extended-B
    (0x0370, 0x03FF),  # Greek and Coptic
    (0x0400, 0x04FF),  # Cyrillic
    (0x1E00, 0x1EFF),  # Latin Extended Additional (Vietnamese, Welsh)
    (0x2000, 0x206F),  # General Punctuation (incl. U+2026 ellipsis)
    (0x20A0, 0x20CF),  # Currency Symbols
    (0x2100, 0x214F),  # Letterlike Symbols (incl. U+2117 sound recording copyright)
    (0x2190, 0x21FF),  # Arrows
    (0x2200, 0x22FF),  # Mathematical Operators
    (0x25A0, 0x25FF),  # Geometric Shapes
    (0x2600, 0x26FF),  # Miscellaneous Symbols
]


def runs(codepoints):
    out = []
    for c in codepoints:
        if out and out[-1][1] == c - 1:
            out[-1][1] = c
        else:
            out.append([c, c])
    return out


def main():
    if len(sys.argv) != 2:
        sys.exit(__doc__)
    here = os.path.dirname(os.path.abspath(__file__))
    src = TTFont(sys.argv[1])
    cmap = src.getBestCmap()
    glyf, hmtx = src["glyf"], src["hmtx"]

    def is_mark(c):  # outlines but no advance
        g = cmap[c]
        return hmtx[g][0] == 0 and glyf[g].numberOfContours != 0

    keep = [c for a, b in BLOCKS for c in range(a, b + 1) if c in cmap and not is_mark(c)]
    # Blank glyphs with a width (no-break and typographic spaces): raylib
    # sizes every blank glyph but U+0020 to zero, src/ui.c restores these.
    blanks = [(c, hmtx[cmap[c]][0]) for c in keep
              if c != 0x20 and glyf[cmap[c]].numberOfContours == 0 and hmtx[cmap[c]][0] > 0]

    opts = subset.Options()
    opts.layout_features = []
    opts.hinting = False
    opts.glyph_names = False
    opts.notdef_outline = False
    opts.name_IDs = ["*"]
    opts.name_languages = ["*"]
    opts.drop_tables += ["GDEF", "GPOS", "GSUB", "gasp", "kern", "DSIG"]
    font = TTFont(sys.argv[1])
    sub = subset.Subsetter(opts)
    sub.populate(unicodes=keep)
    sub.subset(font)
    name = os.path.splitext(os.path.basename(sys.argv[1]))[0]
    ttf = os.path.join(here, name + ".subset.ttf")
    font.save(ttf)

    hhea = src["hhea"]
    version = src["name"].getDebugName(5)
    rs = runs(keep)
    lines = [
        "/* Generated by third_party/inter/subset.py from %s.ttf," % name,
        " * %s. Do not edit. */" % version,
        "",
        "/* The codepoints %s.subset.ttf maps, as inclusive ranges. */" % name,
        "#define INTER_CODEPOINTS %d" % len(keep),
        "static const int inter_ranges[][2] = {",
    ]
    for i in range(0, len(rs), 4):
        lines.append("    " + " ".join("{ 0x%04X, 0x%04X }," % (a, b) for a, b in rs[i:i + 4]))
    lines += [
        "};",
        "",
        "/* Blank glyphs other than U+0020 with their advance in font units:",
        " * raylib gives every blank glyph but the space a zero width. */",
        "static const int inter_blanks[][2] = {",
    ]
    for i in range(0, len(blanks), 4):
        lines.append("    " + " ".join("{ 0x%04X, %d }," % b for b in blanks[i:i + 4]))
    lines += [
        "};",
        "",
        "/* Ascender minus descender in font units: a raylib font size of N px",
        " * scales this height to N. */",
        "#define INTER_HEIGHT %d" % (hhea.ascent - hhea.descent),
        "",
    ]
    with open(os.path.join(here, "inter_subset.h"), "w", newline="\n") as f:
        f.write("\n".join(lines))
    print("%s: %d codepoints in %d ranges, %d bytes" % (ttf, len(keep), len(rs), os.path.getsize(ttf)))


if __name__ == "__main__":
    main()
